{"title":"A truth maintenance system","url":"https://www.sciencedirect.com/science/article/pii/0004370279900080","doi":"10.1016/0004-3702(79)90008-0","authors":["Jon Doyle"],"year":1979,"abstract":"Introduces a truth-maintenance system that records justifications for beliefs and revises the active belief set when new discoveries contradict assumptions, while retaining dependency information useful for explanations and backtracking.","venue":"Artificial Intelligence"}
{"title":"On the logic of theory change: Partial meet contraction and revision functions","url":"https://www.cambridge.org/core/journals/journal-of-symbolic-logic/article/abs/on-the-logic-of-theory-change-partial-meet-contraction-and-revision-functions/7ED837BAD5FB6D9A7C77906D73527F9C","doi":"10.2307/2274239","authors":["Carlos E. Alchourrón","Peter Gärdenfors","David Makinson"],"year":1985,"abstract":"Develops formal postulates and representation results for contraction and revision of belief theories, including partial-meet contraction, providing foundational machinery for distinguishing belief revision from simple addition or deletion.","venue":"The Journal of Symbolic Logic"}
{"title":"An assumption-based TMS","url":"https://www.sciencedirect.com/science/article/pii/0004370286900809","doi":"10.1016/0004-3702(86)90080-9","authors":["Johan de Kleer"],"year":1986,"abstract":"Presents an assumption-based truth-maintenance system that represents alternative assumption sets, supports reasoning with inconsistent information and multiple contexts, and avoids destructive retraction of prior information.","venue":"Artificial Intelligence"}
{"title":"Temporal Interpretation, Discourse Relations, and Commonsense Entailment","url":"https://doi.org/10.1007/BF00986208","doi":"10.1007/BF00986208","authors":["Alex Lascarides","Nicholas Asher"],"year":1993,"abstract":"Provides a formal account of discourse relations and temporal relations between events using defeasible rules and commonsense knowledge, showing how similar surface forms can receive different temporal and discourse interpretations.","venue":"Linguistics and Philosophy"}
{"title":"Discourse Obligations in Dialogue Processing","url":"https://arxiv.org/abs/cmp-lg/9407011","arxiv_id":"cmp-lg/9407011","doi":"10.3115/981732.981733","authors":["David R. Traum","James F. Allen"],"year":1994,"abstract":"Models discourse obligations as dialogue attitudes that persist in conversational context, including obligations created by questions and other dialogue acts, providing a precursor to longitudinal commitment tracking.","venue":"32nd Annual Meeting of the Association for Computational Linguistics"}
{"title":"A Consensus Glossary of Temporal Database Concepts","url":"https://researchnow.flinders.edu.au/en/publications/a-consensus-glossary-of-temporal-database-concepts/","doi":"10.1145/181550.181560","year":1994,"abstract":"Defines and systematizes temporal-database concepts including distinctions needed to represent facts whose validity and database history vary over time, providing terminology relevant to valid-time versus observation or transaction-time reasoning.","venue":"ACM SIGMOD Record"}
{"title":"Operational specification of a commitment-based agent communication language","url":"https://doi.org/10.1145/544862.544868","doi":"10.1145/544862.544868","authors":["Nicoletta Fornara","Marco Colombetti"],"year":2002,"abstract":"Defines agent communication semantics through social commitments, including conditional commitments and precommitments, and specifies how communicative acts operate on commitment objects as interactions evolve.","venue":"AAMAS 2002"}
{"title":"Flexible protocol specification and execution: applying event calculus planning using commitments","url":"https://dblp.org/rec/conf/atal/YolumS02.html","doi":"10.1145/544862.544867","authors":["Pinar Yolum","Munindar P. Singh"],"year":2002,"abstract":"Represents interaction protocols through commitments and uses event-calculus planning to reason about evolving social states, allowing agents more flexibility than protocols defined only as fixed action sequences.","venue":"AAMAS 2002"}
{"title":"TimeML: Robust Specification of Event and Temporal Expressions in Text","url":"https://aaai.org/papers/0005-ss03-07-005-timeml-robust-specification-of-event-and-temporal-expressions-in-text/","authors":["James Pustejovsky","José Castaño","Robert Ingria","Roser Saurí","Robert Gaizauskas","Andrea Setzer","Graham Katz","Dragomir Radev"],"year":2003,"abstract":"Defines TimeML for annotating events, temporal expressions, event-time anchoring, and temporal ordering across sentences and discourse, including underspecified temporal interpretations and modal contexts.","venue":"AAAI Spring Symposium: New Directions in Question Answering"}
{"title":"Classifying Temporal Relations Between Events","url":"https://aclanthology.org/P07-2044/","authors":["Nathanael Chambers","Shan Wang","Dan Jurafsky"],"year":2007,"abstract":"Studies automatic classification of temporal relations between textual events, combining event attributes with learned relation classifiers to support event ordering from natural language.","venue":"ACL 2007"}
{"title":"Jointly Combining Implicit Constraints Improves Temporal Ordering","url":"https://aclanthology.org/D08-1073/","authors":["Nathanael Chambers","Daniel Jurafsky"],"year":2008,"abstract":"Shows that temporal-relation predictions can be improved by joint inference that enforces implicit consistency constraints among relations instead of classifying each event pair independently.","venue":"EMNLP 2008"}
{"title":"Finding Contradictions in Text","url":"https://aclanthology.org/P08-1118/","authors":["Marie-Catherine de Marneffe","Anna N. Rafferty","Christopher D. Manning"],"year":2008,"abstract":"Develops methods and a typology for recognizing textual contradictions, covering phenomena such as negation, antonymy, numeric differences, structural mismatches, and incompatible facts.","venue":"ACL 2008"}
{"title":"Provenance in Databases: Why, How, and Where","url":"https://www.research.ed.ac.uk/en/publications/provenance-in-databases-why-how-and-where/","doi":"10.1561/1900000006","authors":["James Cheney","Laura Chiticariu","Wang Chiew Tan"],"year":2009,"abstract":"Surveys why-, how-, and where-provenance for database queries and their applications to confidence, updates, debugging, and annotation propagation, providing foundations for retaining derivational lineage rather than only current values.","venue":"Foundations and Trends in Databases"}
{"title":"Are You Sure That This Happened? Assessing the Factuality Degree of Events in Text","url":"https://aclanthology.org/J12-2002/","doi":"10.1162/COLI_a_00096","authors":["Roser Saurí","James Pustejovsky"],"year":2012,"abstract":"Models event factuality through polarity and degrees of certainty, addressing whether an event is presented as having happened, not happened, or remaining possible or uncertain.","venue":"Computational Linguistics"}
{"title":"Annotating Story Timelines as Temporal Dependency Structures","url":"https://aclanthology.org/L12-1182/","authors":["Steven Bethard","Oleksandr Kolomiyets","Marie-Francine Moens"],"year":2012,"abstract":"Represents story timelines as temporal dependency trees whose events are linked by relations such as BEFORE, AFTER, inclusion, identity, and overlap, with explicit treatment of modal, negated, and quoted contexts during event selection.","venue":"LREC 2012"}
{"title":"Extracting Narrative Timelines as Temporal Dependency Structures","url":"https://aclanthology.org/P12-1010/","authors":["Oleksandr Kolomiyets","Steven Bethard","Marie-Francine Moens"],"year":2012,"abstract":"Extracts narrative timelines by organizing events into temporal dependency structures rather than isolated pairwise relations, providing a structured representation of event ordering.","venue":"ACL 2012"}
{"title":"Joint Inference for Event Timeline Construction","url":"https://aclanthology.org/D12-1062/","authors":["Quang Do","Wei Lu","Dan Roth"],"year":2012,"abstract":"Constructs event timelines with interval-based temporal representations and joint inference over local temporal classifiers, global constraints, and event-coreference information.","venue":"EMNLP-CoNLL 2012"}
{"title":"User Edits Classification Using Document Revision Histories","url":"https://aclanthology.org/E12-1036/","authors":["Amit Bronner","Christof Monz"],"year":2012,"abstract":"Uses document revision histories to distinguish factual edits from fluency edits, demonstrating that revision sequences can be classified according to the semantic significance of changes rather than only their lexical form.","venue":"EACL 2012"}
{"title":"Correction by adversative and additive markers","url":"https://www.sciencedirect.com/science/article/abs/pii/S0024384112001738","doi":"10.1016/j.lingua.2012.08.015","authors":["Katja Jasinskaja"],"year":2012,"abstract":"Analyzes linguistic correction expressed by adversative and additive markers and develops a semantic-pragmatic account of asymmetric and symmetric corrective constructions.","venue":"Lingua"}
{"title":"Corrective elaboration","url":"https://www.sciencedirect.com/science/article/abs/pii/S0024384112002288","doi":"10.1016/j.lingua.2012.10.010","authors":["Katja Jasinskaja"],"year":2013,"abstract":"Compares correction with elaboration and provides a unified pragmatic account in which discourse context and exhaustivity determine whether a subsequent utterance replaces an earlier alternative or elaborates it.","venue":"Lingua"}
{"title":"Automatically Classifying Edit Categories in Wikipedia Revisions","url":"https://aclanthology.org/D13-1055/","authors":["Johannes Daxenberger","Iryna Gurevych"],"year":2013,"abstract":"Develops automatic classification of Wikipedia revision edits into categories, providing empirical machinery for assigning semantic or functional meaning to changes across document versions.","venue":"EMNLP 2013"}
{"title":"FacTA: Evaluation of Event Factuality and Temporal Anchoring","url":"https://books.openedition.org/aaccademia/13703","authors":["Anne-Lyse Minard","Manuela Speranza","Rachele Sprugnoli","Tommaso Caselli"],"year":2015,"abstract":"Defines an evaluation task that explicitly connects event factuality profiling with temporal anchoring, bringing together whether an event is asserted as real and where it is situated temporally.","venue":"CLiC-it 2015"}
{"title":"Knowledge-Based Trust: Estimating the Trustworthiness of Web Sources","url":"https://arxiv.org/abs/1502.03519","arxiv_id":"1502.03519","authors":["Xin Luna Dong","Evgeniy Gabrilovich","Kevin Murphy","Van Dang","Wilko Horn","Camillo Lugaresi","Shaohua Sun","Wei Zhang"],"year":2015,"abstract":"Estimates source trustworthiness from the correctness of facts attributed to sources and uses joint inference to distinguish source factual errors from information-extraction errors."}
{"title":"Using Context to Predict the Purpose of Argumentative Writing Revisions","url":"https://aclanthology.org/N16-1168/","doi":"10.18653/v1/N16-1168","authors":["Fan Zhang","Diane Litman"],"year":2016,"abstract":"Predicts the purpose of revisions in argumentative writing using contextual information, contributing methods for classifying why a textual revision was made rather than merely detecting its surface change.","venue":"NAACL-HLT 2016"}
{"title":"A Structured Learning Approach to Temporal Relation Extraction","url":"https://arxiv.org/abs/1906.04943","arxiv_id":"1906.04943","doi":"10.18653/v1/D17-1108","authors":["Qiang Ning","Zhili Feng","Dan Roth"],"year":2017,"abstract":"Treats temporal-relation extraction as structured prediction so that dependencies and consistency among event-event relations are considered jointly, including the problem of missing temporal links.","venue":"EMNLP 2017"}
{"title":"Identifying Semantic Edit Intentions from Revisions in Wikipedia","url":"https://aclanthology.org/D17-1213/","doi":"10.18653/v1/D17-1213","authors":["Diyi Yang","Aaron Halfaker","Robert Kraut","Eduard Hovy"],"year":2017,"abstract":"Introduces a taxonomy of semantic intentions behind Wikipedia edits and trains a classifier to infer those intentions from revision data, moving beyond purely syntactic edit operations.","venue":"EMNLP 2017"}
{"title":"An Empirical Analysis of Edit Importance between Document Versions","url":"https://aclanthology.org/D17-1295/","doi":"10.18653/v1/D17-1295","authors":["Tanya Goyal","Sachin Kelkar","Manas Agarwal","Jeenu Grover"],"year":2017,"abstract":"Studies how important individual edits are when comparing successive document versions and models human judgments of whether changes are superficial or substantially alter document content or tone.","venue":"EMNLP 2017"}
{"title":"Tracking State Changes in Procedural Text: A Challenge Dataset and Models for Process Paragraph Comprehension","url":"https://arxiv.org/abs/1805.06975","arxiv_id":"1805.06975","doi":"10.18653/v1/N18-1144","authors":["Bhavana Dalvi Mishra","Lifu Huang","Niket Tandon","Wen-tau Yih","Peter Clark"],"year":2018,"abstract":"Introduces ProPara, a natural-language dataset in which entity existence and location must be tracked step by step through descriptions of changing processes, requiring inference of implicit state transitions.","venue":"NAACL-HLT 2018"}
{"title":"Neural Ranking Models for Temporal Dependency Structure Parsing","url":"https://arxiv.org/abs/1809.00370","arxiv_id":"1809.00370","doi":"10.18653/v1/D18-1371","authors":["Yuchen Zhang","Nianwen Xue"],"year":2018,"abstract":"Builds a neural temporal dependency parser that organizes textual events and time expressions into a temporal dependency tree and evaluates it on both news and narrative domains.","venue":"EMNLP 2018"}
{"title":"MultiFC: A Real-World Multi-Domain Dataset for Evidence-Based Fact Checking of Claims","url":"https://arxiv.org/abs/1909.03242","arxiv_id":"1909.03242","doi":"10.18653/v1/D19-1475","authors":["Isabelle Augenstein","Christina Lioma","Dongsheng Wang","Lucas Chaves Lima","Casper Hansen","Christian Hansen","Jakob Grue Simonsen"],"year":2019,"abstract":"Provides naturally occurring claims from multiple fact-checking domains together with textual evidence, metadata, and expert veracity labels, and jointly studies evidence ranking and claim-veracity prediction.","venue":"EMNLP-IJCNLP 2019"}
{"title":"Do You Know That Florence Is Packed with Visitors? Evaluating State-of-the-art Models of Speaker Commitment","url":"https://aclanthology.org/P19-1412/","doi":"10.18653/v1/P19-1412","authors":["Nanjiang Jiang","Marie-Catherine de Marneffe"],"year":2019,"abstract":"Evaluates speaker-commitment and event-factuality models on naturally occurring discourse, showing that commitment depends on linguistic context such as negation, modality, questions, and conditionals.","venue":"ACL 2019"}
{"title":"Inherent Disagreements in Human Textual Inferences","url":"https://aclanthology.org/Q19-1043/","doi":"10.1162/tacl_a_00293","authors":["Ellie Pavlick","Tom Kwiatkowski"],"year":2019,"abstract":"Shows that disagreement about natural-language inference often persists rather than disappearing as annotation noise and argues that models should preserve distributions of plausible judgments rather than force a single interpretation.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"Tracking Discrete and Continuous Entity State for Process Understanding","url":"https://arxiv.org/abs/1904.03518","arxiv_id":"1904.03518","doi":"10.18653/v1/W19-1502","authors":["Aditya Gupta","Greg Durrett"],"year":2019,"abstract":"Tracks evolving entity states through procedural text with a model combining recurrent continuous representations and globally constrained discrete states, enforcing consistency across process steps.","venue":"Third Workshop on Structured Prediction for NLP"}
{"title":"Fact or Fiction: Verifying Scientific Claims","url":"https://arxiv.org/abs/2004.14974","arxiv_id":"2004.14974","doi":"10.18653/v1/2020.emnlp-main.609","authors":["David Wadden","Shanchuan Lin","Kyle Lo","Lucy Lu Wang","Madeleine van Zuylen","Arman Cohan","Hannaneh Hajishirzi"],"year":2020,"abstract":"Introduces scientific claim verification in which systems retrieve evidence-containing abstracts, decide whether evidence supports or refutes a claim, and identify the rationale for that decision.","venue":"EMNLP 2020"}
{"title":"Exploring Contextualized Neural Language Models for Temporal Dependency Parsing","url":"https://aclanthology.org/2020.emnlp-main.689/","doi":"10.18653/v1/2020.emnlp-main.689","authors":["Hayley Ross","Jonathon Cai","Bonan Min"],"year":2020,"abstract":"Evaluates contextualized neural language models for temporal dependency parsing, which links events and time expressions into document-level temporal structures rather than treating temporal relations independently.","venue":"EMNLP 2020"}
{"title":"A Dataset for Tracking Entities in Open Domain Procedural Text","url":"https://arxiv.org/abs/2011.08092","arxiv_id":"2011.08092","doi":"10.18653/v1/2020.emnlp-main.520","authors":["Niket Tandon","Keisuke Sakaguchi","Bhavana Dalvi Mishra","Dheeraj Rajagopal","Peter Clark","Michal Guerquin","Kyle Richardson","Eduard Hovy"],"year":2020,"abstract":"Introduces OPENPI, where systems generate open-vocabulary tuples describing an entity, changed attribute, before-state, and after-state at each step of natural procedural text.","venue":"EMNLP 2020"}
{"title":"HoVer: A Dataset for Many-Hop Fact Extraction And Claim Verification","url":"https://arxiv.org/abs/2011.03088","arxiv_id":"2011.03088","doi":"10.18653/v1/2020.findings-emnlp.309","authors":["Yichen Jiang","Shikha Bordia","Zheng Zhong","Charles Dognin","Maneesh Singh","Mohit Bansal"],"year":2020,"abstract":"Requires systems to gather evidence distributed across multiple documents and determine whether a claim is supported, providing a testbed for corroborative reasoning over several evidence sources.","venue":"Findings of EMNLP 2020"}
{"title":"Get Your Vitamin C! Robust Fact Verification with Contrastive Evidence","url":"https://aclanthology.org/2021.naacl-main.52/","doi":"10.18653/v1/2021.naacl-main.52","authors":["Tal Schuster","Adam Fisch","Regina Barzilay"],"year":2021,"abstract":"Builds a fact-verification benchmark from Wikipedia revisions that change underlying facts, pairing near-identical but factually contrasting evidence and explicitly testing sensitivity to evidence that changes over time.","venue":"NAACL-HLT 2021"}
{"title":"Factuality Assessment as Modal Dependency Parsing","url":"https://aclanthology.org/2021.acl-long.122/","doi":"10.18653/v1/2021.acl-long.122","authors":["Jiarui Yao","Haoling Qiu","Jin Zhao","Bonan Min","Nianwen Xue"],"year":2021,"abstract":"Frames event factuality as modal dependency parsing that jointly identifies events, their source or conceiver, and the certainty with which each source commits to those events.","venue":"ACL-IJCNLP 2021"}
{"title":"Identifying inherent disagreement in natural language inference","url":"https://aclanthology.org/2021.naacl-main.390/","doi":"10.18653/v1/2021.naacl-main.390","authors":["Xinliang Frederick Zhang","Marie-Catherine de Marneffe"],"year":2021,"abstract":"Distinguishes NLI cases with systematic agreement from cases with genuine annotation disagreement and models multiple plausible interpretations instead of collapsing all examples to a single certain label.","venue":"NAACL-HLT 2021"}
{"title":"One Document, Many Revisions: A Dataset for Classification and Description of Edit Intents","url":"https://aclanthology.org/2022.lrec-1.591/","authors":["Dheeraj Rajagopal","Xuchao Zhang","Michael Gamon","Sujay Kumar Jauhar","Diyi Yang","Eduard Hovy"],"year":2022,"abstract":"Provides full Wikipedia revision histories annotated for edit intent and studies both classification of revision purposes and generation of free-form descriptions of changes across document versions.","venue":"LREC 2022"}
{"title":"Investigating Reasons for Disagreement in Natural Language Inference","url":"https://aclanthology.org/2022.tacl-1.78/","doi":"10.1162/tacl_a_00523","authors":["Nan-Jiang Jiang","Marie-Catherine de Marneffe"],"year":2022,"abstract":"Develops a taxonomy of sources of disagreement in natural-language inference and evaluates modeling approaches that retain multiple possible labels when evidence or interpretation does not warrant a single resolved judgment.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"Event Semantic Knowledge in Procedural Text Understanding","url":"https://aclanthology.org/2023.starsem-1.33/","doi":"10.18653/v1/2023.starsem-1.33","authors":["Ghazaleh Kazeminejad","Martha Palmer"],"year":2023,"abstract":"Studies entity-state tracking in procedural text and injects event-semantic knowledge to infer changes that are often implicit in verbs and commonsense process descriptions.","venue":"*SEM 2023"}
{"title":"Discourse Information for Document-Level Temporal Dependency Parsing","url":"https://aclanthology.org/2023.codi-1.10/","doi":"10.18653/v1/2023.codi-1.10","authors":["Jingcheng Niu","Victoria Ng","Erin Rees","Simon De Montigny","Gerald Penn"],"year":2023,"abstract":"Examines document-level temporal dependency parsing with discourse and sentence-position information, constructing temporal dependency graphs across a document rather than isolated event pairs.","venue":"CODI 2023"}
{"title":"Re3: A Holistic Framework and Dataset for Modeling Collaborative Document Revision","url":"https://arxiv.org/abs/2406.00197","arxiv_id":"2406.00197","doi":"10.18653/v1/2024.acl-long.255","authors":["Qian Ruan","Ilia Kuznetsov","Iryna Gurevych"],"year":2024,"abstract":"Introduces a framework linking document revisions, reviews, and author responses, with aligned scientific-paper revisions labeled by revision action and intent and accompanied by reviews and edit summaries.","venue":"ACL 2024"}
{"title":"ECON: On the Detection and Resolution of Evidence Conflicts","url":"https://arxiv.org/abs/2410.04068","arxiv_id":"2410.04068","doi":"10.18653/v1/2024.emnlp-main.447","authors":["Cheng Jiayang","Chunkit Chan","Qianqian Zhuang","Lin Qiu","Tianhang Zhang","Tengxiao Liu","Yangqiu Song","Yue Zhang","Pengfei Liu","Zheng Zhang"],"year":2024,"abstract":"Studies detection and resolution of conflicts between pieces of evidence, evaluating NLI, factual-consistency models, and LLMs and showing that conflict resolution can select one source without an adequate evidential justification.","venue":"EMNLP 2024"}
{"title":"What Evidence Do Language Models Find Convincing?","url":"https://arxiv.org/abs/2402.11782","arxiv_id":"2402.11782","doi":"10.18653/v1/2024.acl-long.403","authors":["Alexander Wan","Eric Wallace","Dan Klein"],"year":2024,"abstract":"Introduces ConflictingQA, pairing contentious queries with real-world evidence documents that disagree in facts and answers, and examines which evidence characteristics influence model arbitration under conflict.","venue":"ACL 2024"}
{"title":"ProPara-CRTS: Canonical Referent Tracking for Reliable Evaluation of Entity State Tracking in Process Narratives","url":"https://aclanthology.org/2025.iwcs-main.22/","authors":["Bingyang Ye","Timothy Obiso","Jingxuan Tu","James Pustejovsky"],"year":2025,"abstract":"Introduces a canonical referent tracking schema in which surface mentions map to immutable discourse referents whose existence and location are recorded at each process step, supporting more reliable longitudinal state histories.","venue":"IWCS 2025"}
{"title":"When Text and Numbers Disagree: Evidence Arbitration in Large Language Models","url":"https://arxiv.org/abs/2608.20116","arxiv_id":"2608.20116","authors":["Mattia Carletti","Edward Phillips","Fredrik K. Gustafsson","Patitapaban Palo","Lei Clifton","Danielle Belgrave","Xiao Gu","David A. Clifton"],"year":2026,"published":"2026-08-20","abstract":"Uses a controlled synthetic benchmark with conflicting textual and numerical evidence to test arbitration while independently varying temporal recency, source reliability, modality, and provenance; the study finds systematic evidence-selection heuristics rather than reliable provenance-sensitive resolution.","venue":"arXiv"}
===END llm_candidates.jsonl===
